import type { Redis } from 'ioredis'; import { CLICK_STREAM } from '../config/constants.js'; export async function publishClick(redis:Redis,event:{urlId:string;referrer?:string;userAgent?:string;country?:string}){try {await redis.xadd(CLICK_STREAM,'*','urlId',event.urlId,'referrer',event.referrer??'','userAgent',event.userAgent??'','country',event.country??'')}catch{ /* analytics is best effort when Redis is unavailable */ }}
